<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import type { BluetoothView,BluetoothAction } from './connectivity';
  let view=$state<BluetoothView|null>(null),busy=$state(false),error=$state(''),reply=$state('');
  let confirmation=$state<{action:BluetoothAction;message:string}|null>(null);
  let pairingActive=$derived(!!view?.pairing&&['pairing','waiting'].includes(view.pairing.phase));
  let alive=true,polling=false,revision=0,lease:number|null=null;
  let lastPrompt='';
  $effect(()=>{if(confirmation)void tick().then(()=>document.getElementById('bluetooth-confirmation')?.focus());});
  $effect(()=>{const prompt=view?.pairing?.prompt??'';if(prompt&&prompt!==lastPrompt){lastPrompt=prompt;void tick().then(()=>{const target=document.getElementById('bluetooth-reply')??document.getElementById('bluetooth-confirm-code');target?.scrollIntoView({block:'center'});target?.focus({preventScroll:true});});}else if(!prompt)lastPrompt='';});
  async function open(){busy=true;error='';try{const next=await invoke<BluetoothView>('open_bluetooth');lease=next.lease;if(alive)view=next;else await invoke('close_bluetooth',{lease});}catch(cause){if(alive)error=String(cause);}finally{if(alive)busy=false;}}
  async function refresh(clearError=false){if(busy||polling||lease===null)return;polling=true;const token=revision;try{const next=await invoke<BluetoothView>('get_bluetooth',{lease});if(alive&&token===revision){view=next;if(clearError)error='';}}catch(cause){if(alive&&token===revision)error=String(cause);}finally{polling=false;}}
  async function apply(action:BluetoothAction){if(busy||lease===null)return;revision++;busy=true;error='';confirmation=null;try{const next=await invoke<BluetoothView>('apply_bluetooth',{lease,action});if(alive){view=next;reply='';}}catch(cause){if(alive)error=String(cause);}finally{if(alive)busy=false;}}
  onMount(()=>{void open();const timer=window.setInterval(()=>void refresh(),1000);return()=>{alive=false;reply='';window.clearInterval(timer);if(lease!==null)void invoke('close_bluetooth',{lease}).catch(()=>{});};});
</script>
<div class="page-heading"><div><div class="eyebrow">YOUR DEVICES, TOGETHER</div><h1>Bluetooth</h1><p>Discover, pair, and connect nearby devices.</p></div><button class="quiet" disabled={busy} onclick={()=>view?refresh(true):open()}>Refresh</button></div>
{#if error}<div class="notice error" role="alert">{error}</div>{/if}
{#if confirmation}<section id="bluetooth-confirmation" tabindex="-1" class="connection-prompt" role="group" aria-label="Confirm Bluetooth change"><h2>Change this device?</h2><p>{confirmation.message}</p><button class="quiet" onclick={()=>confirmation=null}>Cancel</button><button class="primary" onclick={()=>{if(confirmation)void apply(confirmation.action);}}>Confirm Bluetooth change</button></section>{/if}
{#if view}
  <section class="section"><h2>Bluetooth</h2><div class="settings-card"><div class="setting-row"><div><label for="bluetooth-power">Bluetooth</label><p>Use BlueZ to connect headphones, keyboards, and other devices.</p></div><input id="bluetooth-power" class="switch" type="checkbox" role="switch" disabled={busy||pairingActive} checked={view.snapshot.powered} onchange={event=>{const enabled=event.currentTarget.checked;event.currentTarget.checked=!!view?.snapshot.powered;if(enabled)void apply({type:'set_power',enabled:true});else confirmation={action:{type:'set_power',enabled:false},message:'Turn off Bluetooth? Connected keyboards, mice, and audio devices will disconnect.'};}} /></div><div class="setting-row"><div><strong>{view.snapshot.scanning?'Looking for nearby devices…':'Device discovery'}</strong><p>Discovery stops after 30 seconds or when you leave this page.</p></div><button class="quiet" disabled={busy||pairingActive||!view.snapshot.powered} onclick={()=>apply({type:view?.snapshot.scanning?'stop_scan':'scan'})}>{view.snapshot.scanning?'Stop discovery':'Find devices'}</button></div></div></section>
  {#if view.pairing}<section class="connection-prompt" role="status" aria-live="polite"><h2>{view.pairing.phase==='succeeded'?'Device paired':view.pairing.phase==='failed'?'Pairing ended':'Pairing device'}</h2><p>{view.pairing.address}</p><p>{view.pairing.message}</p>{#if view.pairing.prompt}<pre id="bluetooth-confirm-code" tabindex="-1">{view.pairing.prompt}</pre>{#if view.pairing.kind==='confirm'}<p>Confirm only if the code matches the code shown on your device.</p><button class="quiet" disabled={busy} onclick={()=>apply({type:'reply',value:'no'})}>Reject code</button><button class="primary" disabled={busy} onclick={()=>apply({type:'reply',value:'yes'})}>Codes match</button>{:else}<label for="bluetooth-reply">{view.pairing.kind==='passkey'?'Six-digit passkey':'PIN from your device'}</label><input id="bluetooth-reply" type="password" autocomplete="off" maxlength="16" bind:value={reply} /><button class="primary" disabled={busy||!reply} onclick={()=>apply({type:'reply',value:reply})}>Send pairing code</button>{/if}{/if}{#if pairingActive}<div class="actions"><button class="quiet" disabled={busy} onclick={()=>apply({type:'cancel_pairing'})}>Cancel pairing</button></div>{/if}</section>{/if}
  <section class="section"><h2>Devices</h2><div class="settings-card">{#each view.snapshot.devices as device}<div class="setting-row"><div><strong>{device.name}</strong><p>{device.address} · {device.connected?'Connected':device.paired?'Paired':'Not paired'}</p></div><div class="actions">{#if device.connected}<button class="quiet" disabled={busy||pairingActive} aria-label={`Disconnect ${device.name}`} onclick={()=>confirmation={action:{type:'disconnect',address:device.address},message:`Disconnect ${device.name}? Input or audio from this device will stop.`}}>Disconnect</button>{:else if device.paired}<button class="quiet" disabled={busy||pairingActive||!view.snapshot.powered} aria-label={`Connect ${device.name}`} onclick={()=>apply({type:'connect',address:device.address})}>Connect</button>{:else}<button class="quiet" disabled={busy||pairingActive||!view.snapshot.powered} aria-label={`Pair ${device.name}`} onclick={()=>apply({type:'pair',address:device.address})}>Pair</button>{/if}{#if device.paired}<button class="quiet" disabled={busy||pairingActive} aria-label={`Forget ${device.name}`} onclick={()=>confirmation={action:{type:'forget',address:device.address},message:`Forget ${device.name}? Its saved pairing will be removed and it must be paired again.`}}>Forget</button>{/if}</div></div>{:else}<div class="setting-row"><p>{view.snapshot.powered?'No devices found. Put your device in pairing mode, then choose Find devices.':'Turn on Bluetooth to use your devices.'}</p></div>{/each}</div></section>
  <p class="footnote">Pairing uses an explicit confirmation or PIN reply. Leaving this page cancels the pairing helper. Pairings already completed remain saved by BlueZ.</p>
{:else if !error}<div class="loading" role="status">Reading BlueZ state…</div>{/if}
<style>
  strong{font-size:13px;font-weight:550}.actions{display:flex;gap:8px;flex-wrap:wrap}.connection-prompt{border:1px solid var(--fd-border);background:var(--fd-surface);border-radius:var(--fd-radius);padding:22px;margin:20px 0}.connection-prompt p{font-size:12px;line-height:1.8;color:var(--fd-text-muted);margin:12px 0}.connection-prompt pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:15px;background:var(--fd-accent-soft);border-radius:8px;font-size:13px}.connection-prompt label{display:block;margin:12px 0;font-size:12px}.connection-prompt input{padding:10px;border:1px solid var(--fd-border);border-radius:8px;max-width:100%}.connection-prompt .primary{margin-left:8px}.primary{background:var(--fd-accent);color:white;padding:10px 14px;border-radius:8px;font-size:12px}.connection-prompt .actions{margin-top:16px}.footnote{line-height:1.8}
</style>
